class AppConfig {
  AppConfig._();

  // --- Firebase (authentication + database) -------------------------------

  /// Firebase is configured through `lib/firebase_options.dart`, generated by
  /// `dart run flutterfire configure` (see README — Firebase section).
  static bool get useFirebaseAuth => true;

  /// Set to `true` to skip Firebase entirely and fall back to the GitHub
  /// OAuth device flow — useful for tester builds without a Firebase project:
  /// `flutter run --dart-define=USE_DEVICE_FLOW=true`.
  static const bool useDeviceFlowFallback = String.fromEnvironment(
    'USE_DEVICE_FLOW',
    defaultValue: 'false',
  ) == 'true';

  /// GitHub scopes requested from Supabase — identity only.
  ///
  /// Repository access is granted separately through a GitHub App (see
  /// `functions/src/github.ts`), so the app never asks for `repo` and the
  /// user is never forced to hand over every private repository.
  static const String githubScopes = 'read:user user:email';
}
